/**
 * Project countries-110m + d3 graticule at the rest pose used by mount.js
 * and boot-splash-still-svg-pure. Writes boot-splash-still-geo.generated.ts.
 *
 * Run from repo root:
 *   node packages/studio/studio-core/scripts/generate-boot-splash-still-geo.mjs
 */
import { createContext, runInContext } from "node:vm";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const splashDir = resolve(
  here,
  "../../../../apps/studio/public/glass-box-splash",
);
const outFile = resolve(here, "../src/boot-splash-still-geo.generated.ts");

const CENTER_X = 600;
const CENTER_Y = 350;
const GLOBE_RADIUS = 148;
const ROT_X = 0;
const ROT_Y = -12;
const GRAT_STEP = 18;

function loadUmd(fileName, exportName) {
  const code = readFileSync(resolve(splashDir, fileName), "utf8");
  const sandbox = {
    console,
    exports: {},
    module: { exports: {} },
  };
  sandbox.self = sandbox;
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  runInContext(code, createContext(sandbox), { filename: fileName });
  const fromGlobal = sandbox[exportName];
  const fromModule = sandbox.module.exports;
  const fromExports = sandbox.exports[exportName] || sandbox.exports;
  const value =
    fromGlobal && typeof fromGlobal === "object" && Object.keys(fromGlobal).length
      ? fromGlobal
      : fromModule && Object.keys(fromModule).length
        ? fromModule
        : fromExports;
  if (!value || typeof value !== "object") {
    throw new Error(`UMD load failed: ${fileName} (${exportName})`);
  }
  return value;
}

const d3 = loadUmd("d3.min.js", "d3");
const topojson = loadUmd("topojson-client.min.js", "topojson");
if (typeof d3.geoOrthographic !== "function") {
  const keys = Object.keys(d3).slice(0, 30).join(",");
  throw new Error(
    `d3.geoOrthographic missing; typeof=${typeof d3} keys=${keys}`,
  );
}
const world = JSON.parse(
  readFileSync(resolve(splashDir, "countries-110m.json"), "utf8"),
);
if (!world?.objects?.land) {
  throw new Error("countries-110m.json missing objects.land");
}

const projection = d3
  .geoOrthographic()
  .scale(GLOBE_RADIUS)
  .translate([CENTER_X, CENTER_Y])
  .clipAngle(90)
  .rotate([ROT_X, ROT_Y, 0]);
const path = d3.geoPath().projection(projection);
const land = topojson.feature(world, world.objects.land);
const graticule = d3.geoGraticule().step([GRAT_STEP, GRAT_STEP])();
const landD = path(land) || "";
const graticuleD = path(graticule) || "";
if (landD.length < 800 || graticuleD.length < 400) {
  throw new Error(
    `geo paths too small: land=${landD.length} grat=${graticuleD.length}`,
  );
}

function tsString(s) {
  return JSON.stringify(s);
}

const body =
  "/** Generated by generate-boot-splash-still-geo.mjs — do not edit by hand. */\n" +
  `export const BOOT_SPLASH_STILL_GEO_ROT_X = ${ROT_X};\n` +
  `export const BOOT_SPLASH_STILL_GEO_ROT_Y = ${ROT_Y};\n` +
  `export const BOOT_SPLASH_STILL_GEO_GRAT_STEP = ${GRAT_STEP};\n` +
  `export const BOOT_SPLASH_STILL_LAND_D = ${tsString(landD)};\n` +
  `export const BOOT_SPLASH_STILL_GRATICULE_D = ${tsString(graticuleD)};\n`;

writeFileSync(outFile, body);
console.log(
  `wrote ${outFile} land=${landD.length} grat=${graticuleD.length}`,
);
